func checkLevel(_ level: Int) -> String {
    switch level {
    case 1...10:
        return "Beginner"
    case 11...20:
        return "Expert"
    default:
        return "Unknown"
    }
}
print(checkLevel(15))

func validateAge(_ age: Int?) -> String {
    guard let age, age >= 18 else {
        return "Invalid"
    }
    return "Adult: \(age)"
}
print(validateAge(21))

